where not exists (
  select 1 from public.prompts p
  where p.writing_type = 'sentence'
    and p.difficulty = v.level
    and p.category = v.category
    and p.prompt_text = v.vietnamese
);

-- Accepted answers with grammar notes for the 200 intermediate sentences above (2 answers per sentence).
-- Run AFTER the prompts above and migration 0008_accepted_answers.sql. Safe to re-run: a prompt that already has
-- answers keeps them, so anything an admin edited is never overwritten.
-- Each answer: {"text": a correct English sentence, "structureVi": grammar notes in Vietnamese, "structureEn": the same in English}.
insert into public.prompt_answers (prompt_id, answers)
select p.id, v.answers
from (values
  ('intermediate', 'personal-communication', 'Tôi đã nhắn cho bạn hai lần nhưng vẫn chưa nhận được câu trả lời.', $j$[{"text": "I messaged you twice, but I still haven't received a reply.", "structureVi": "message + người: nhắn tin cho ai\nstill + have not + V3: vẫn chưa (hiện tại hoàn thành)", "structureEn": "message + person: text someone\nstill + have not + V3: present perfect, not yet done"}, {"text": "I've sent you two messages, but I'm still waiting for an answer.", "structureVi": "send + người + vật: gửi cho ai cái gì\nbe still waiting for: vẫn đang chờ", "structureEn": "send + person + thing: send someone something\nbe still waiting for: no result yet"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Trước khi đưa ra kết luận, chúng ta nên nghe ý kiến của cả hai bên.', $j$[{"text": "Before we reach a conclusion, we should hear both sides.", "structureVi": "Before + mệnh đề: trước khi\nshould + V: nên làm gì", "structureEn": "Before + clause: before an action\nshould + V: advice"}, {"text": "We should listen to both parties before drawing a conclusion.", "structureVi": "before + V-ing: trước khi làm gì\ndraw a conclusion: đưa ra kết luận", "structureEn": "before + V-ing: before + gerund\ndraw a conclusion: reach a decision"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Cô ấy thường gọi điện cho bố mẹ vào giờ nghỉ trưa.', $j$[{"text": "She usually calls her parents during her lunch break.", "structureVi": "usually + V: thường làm gì\ncall + người: gọi điện cho ai", "structureEn": "usually + V: most of the time\ncall + person: phone someone"}, {"text": "She often phones her parents at lunchtime.", "structureVi": "often + V: thường\nat lunchtime: vào giờ nghỉ trưa", "structureEn": "often + V: frequently\nat lunchtime: at the midday break"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Tôi muốn giải thích rõ hơn để tránh hiểu lầm không đáng có.', $j$[{"text": "I want to explain it more clearly to avoid an unnecessary misunderstanding.", "structureVi": "want to + V: muốn làm gì\navoid + danh từ: tránh điều gì", "structureEn": "want to + V: express a wish\navoid + noun: stay away from something"}, {"text": "I'd like to make it clearer so that we don't misunderstand each other.", "structureVi": "would like to + V: muốn (lịch sự)\nso that + mệnh đề: để mà", "structureEn": "would like to + V: polite wish\nso that + clause: purpose"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Nếu bạn đến muộn, hãy báo cho mọi người biết trước.', $j$[{"text": "If you are going to be late, please let everyone know in advance.", "structureVi": "If + hiện tại đơn, mệnh lệnh: câu điều kiện loại 1\nlet + người + know: cho ai biết", "structureEn": "If + present simple, imperative: first conditional\nlet + person + know: inform someone"}, {"text": "Tell everyone beforehand if you arrive late.", "structureVi": "tell + người: nói cho ai biết\nbeforehand: trước đó", "structureEn": "tell + person: inform someone\nbeforehand: in advance"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Anh ấy xin lỗi vì đã quên cuộc hẹn của chúng tôi.', $j$[{"text": "He apologized for forgetting our appointment.", "structureVi": "apologize for + V-ing: xin lỗi vì đã làm gì\nforget + danh từ: quên", "structureEn": "apologize for + V-ing: say sorry for an action\nforget + noun: fail to remember"}, {"text": "He said sorry because he had forgotten about our meeting.", "structureVi": "had + V3: quá khứ hoàn thành, việc xảy ra trước\nbecause + mệnh đề: bởi vì", "structureEn": "had + V3: past perfect, earlier action\nbecause + clause: reason"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Chúng tôi giữ liên lạc dù sống ở hai thành phố khác nhau.', $j$[{"text": "We keep in touch even though we live in two different cities.", "structureVi": "keep in touch: giữ liên lạc\neven though + mệnh đề: mặc dù", "structureEn": "keep in touch: stay in contact\neven though + clause: contrast"}, {"text": "We stay in contact although we live in different cities.", "structureVi": "stay in contact: giữ liên lạc\nalthough + mệnh đề: mặc dù", "structureEn": "stay in contact: keep communicating\nalthough + clause: contrast"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Tôi không biết cách từ chối lời mời mà không làm bạn buồn.', $j$[{"text": "I don't know how to turn down an invitation without upsetting my friend.", "structureVi": "know how to + V: biết cách làm gì\nturn down: từ chối", "structureEn": "know how to + V: have the skill to do\nturn down: refuse"}, {"text": "I'm not sure how to decline an invitation without hurting my friend's feelings.", "structureVi": "be not sure how to + V: không chắc cách làm gì\ndecline: từ chối (trang trọng)", "structureEn": "be not sure how to + V: unsure about a method\ndecline: formal refuse"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Cô ấy đã chuyển tiếp email cho toàn bộ nhóm dự án.', $j$[{"text": "She forwarded the email to the whole project team.", "structureVi": "forward + vật + to + người: chuyển tiếp cho ai\nquá khứ đơn: việc đã xảy ra", "structureEn": "forward + thing + to + person: pass on a message\npast simple: finished action"}, {"text": "She has forwarded the email to everyone in the project group.", "structureVi": "has + V3: hiện tại hoàn thành\neveryone in + nhóm: mọi người trong nhóm", "structureEn": "has + V3: present perfect\neveryone in + group: all members"}]$j$::jsonb),
  ('intermediate', 'personal-communication', 'Một cuộc trò chuyện chân thành có thể giải quyết nhiều vấn đề.', $j$[{"text": "A sincere conversation can solve many problems.", "structureVi": "can + V: có thể làm gì\nsincere: chân thành", "structureEn": "can + V: possibility\nsincere: honest and genuine"}, {"text": "An honest talk can help resolve a lot of problems.", "structureVi": "help + V: giúp làm gì\na lot of + danh từ: nhiều", "structureEn": "help + V: contribute to\na lot of + noun: many"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Tôi thường chuẩn bị bữa trưa từ tối hôm trước để tiết kiệm thời gian.', $j$[{"text": "I usually prepare my lunch the night before to save time.", "structureVi": "the night before: tối hôm trước\nto + V: để làm gì (mục đích)", "structureEn": "the night before: the evening earlier\nto + V: purpose"}, {"text": "I often make lunch the evening before so I can save time.", "structureVi": "so + chủ ngữ + can: để có thể\nsave time: tiết kiệm thời gian", "structureEn": "so + subject + can: purpose\nsave time: use less time"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Dù bận rộn, gia đình tôi vẫn cố gắng ăn tối cùng nhau.', $j$[{"text": "Even though we are busy, my family tries to have dinner together.", "structureVi": "Even though + mệnh đề: mặc dù\ntry to + V: cố gắng làm gì", "structureEn": "Even though + clause: contrast\ntry to + V: make an effort"}, {"text": "Despite being busy, my family still tries to eat dinner together.", "structureVi": "Despite + V-ing: mặc dù\nstill + V: vẫn", "structureEn": "Despite + V-ing: contrast\nstill + V: continue anyway"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Tôi đang sắp xếp lại tủ quần áo để bỏ những món không dùng nữa.', $j$[{"text": "I'm rearranging my wardrobe to get rid of the things I no longer use.", "structureVi": "am + V-ing: đang làm gì\nget rid of: bỏ đi", "structureEn": "am + V-ing: happening now\nget rid of: throw away"}, {"text": "I'm sorting out my closet so I can throw away clothes I don't wear anymore.", "structureVi": "sort out: sắp xếp lại\nno longer = not anymore: không còn nữa", "structureEn": "sort out: organize\nnot anymore: no longer"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Nếu chia việc nhà hợp lý, mọi người sẽ đỡ mệt hơn.', $j$[{"text": "If we share the housework fairly, everyone will be less tired.", "structureVi": "If + hiện tại đơn, will + V: điều kiện loại 1\nless + tính từ: bớt hơn", "structureEn": "If + present simple, will + V: first conditional\nless + adjective: not as much"}, {"text": "When housework is divided fairly, everyone gets less exhausted.", "structureVi": "be + V3 (bị động): việc nhà được chia\nget + tính từ: trở nên", "structureEn": "be + V3 (passive): chores are divided\nget + adjective: become"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Căn hộ này khá nhỏ nhưng có đủ không gian cho cả gia đình.', $j$[{"text": "This apartment is quite small, but it has enough space for the whole family.", "structureVi": "quite + tính từ: khá\nenough + danh từ: đủ", "structureEn": "quite + adjective: fairly\nenough + noun: sufficient amount"}, {"text": "The flat is rather small, yet there is enough room for all of us.", "structureVi": "rather + tính từ: khá là\nThere is + danh từ: có", "structureEn": "rather + adjective: fairly\nThere is + noun: something exists"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Tôi thường viết danh sách việc cần làm trước khi bắt đầu ngày mới.', $j$[{"text": "I usually write a to-do list before I start my day.", "structureVi": "write a list: viết danh sách\nbefore + mệnh đề: trước khi", "structureEn": "write a list: make a list\nbefore + clause"}, {"text": "I normally make a list of tasks before starting the day.", "structureVi": "a list of + danh từ: danh sách các...\nbefore + V-ing: trước khi", "structureEn": "a list of + noun: items together\nbefore + V-ing: before + gerund"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Mất điện khiến chúng tôi phải thay đổi kế hoạch buổi tối.', $j$[{"text": "The power outage forced us to change our plans for the evening.", "structureVi": "force + người + to + V: buộc ai phải làm gì\npower outage: mất điện", "structureEn": "force + person + to + V: make someone do\npower outage: loss of electricity"}, {"text": "Because the power went out, we had to change our evening plans.", "structureVi": "Because + mệnh đề: bởi vì\nhad to + V: đã phải làm gì", "structureEn": "Because + clause: reason\nhad to + V: past obligation"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Tôi cố gắng hạn chế dùng điện thoại trước khi đi ngủ.', $j$[{"text": "I try to limit my phone use before going to bed.", "structureVi": "try to + V: cố gắng làm gì\nlimit + danh từ: hạn chế", "structureEn": "try to + V: make an effort\nlimit + noun: reduce"}, {"text": "I try not to use my phone too much before I sleep.", "structureVi": "try not to + V: cố gắng không làm gì\ntoo much: quá nhiều", "structureEn": "try not to + V: negative effort\ntoo much: more than needed"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Cô ấy mua thực phẩm cho cả tuần vào sáng Chủ nhật.', $j$[{"text": "She buys groceries for the whole week on Sunday morning.", "structureVi": "buy groceries: mua thực phẩm\non + thời điểm: vào", "structureEn": "buy groceries: shop for food\non + time: specific day"}, {"text": "She does the weekly grocery shopping on Sunday mornings.", "structureVi": "do the shopping: đi mua sắm\non Sunday mornings: vào các sáng Chủ nhật", "structureEn": "do the shopping: buy things\non Sunday mornings: every Sunday morning"}]$j$::jsonb),
  ('intermediate', 'everyday-life', 'Một lịch sinh hoạt ổn định giúp tôi làm việc hiệu quả hơn.', $j$[{"text": "A stable routine helps me work more efficiently.", "structureVi": "help + người + V: giúp ai làm gì\nmore + trạng từ: hiệu quả hơn", "structureEn": "help + person + V: assist someone\nmore + adverb: comparative"}, {"text": "Having a steady schedule makes me more productive.", "structureVi": "V-ing làm chủ ngữ: việc có lịch\nmake + người + tính từ: khiến ai trở nên", "structureEn": "V-ing as subject: having a schedule\nmake + person + adjective: cause a state"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Chúng tôi phải đổi tàu ở ga trung tâm để đến điểm cuối.', $j$[{"text": "We have to change trains at the central station to reach the final stop.", "structureVi": "have to + V: phải làm gì\nto + V: để làm gì", "structureEn": "have to + V: obligation\nto + V: purpose"}, {"text": "We need to transfer at the central station to get to the last stop.", "structureVi": "need to + V: cần làm gì\ntransfer: đổi tuyến", "structureEn": "need to + V: necessity\ntransfer: change lines"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Tôi đặt phòng khách sạn gần ga để tiện di chuyển.', $j$[{"text": "I booked a hotel room near the station so that it would be convenient to get around.", "structureVi": "book + danh từ: đặt\nso that + would: để mà (quá khứ)", "structureEn": "book + noun: reserve\nso that + would: purpose in the past"}, {"text": "I reserved a hotel close to the station for easy travel.", "structureVi": "reserve: đặt trước\nclose to + nơi: gần", "structureEn": "reserve: book in advance\nclose to + place: near"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Do đường bị sửa chữa, xe buýt hôm nay chạy chậm hơn thường lệ.', $j$[{"text": "Because the road is being repaired, the bus is slower than usual today.", "structureVi": "be being + V3: đang được (bị động tiếp diễn)\nslower than usual: chậm hơn thường lệ", "structureEn": "be being + V3: passive continuous\nslower than usual: comparative"}, {"text": "Due to roadworks, the bus is running slower than normal today.", "structureVi": "Due to + danh từ: do, vì\nrun slower: chạy chậm hơn", "structureEn": "Due to + noun: because of\nrun slower: move more slowly"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Bạn nên kiểm tra giờ khởi hành trước khi rời khỏi nhà.', $j$[{"text": "You should check the departure time before you leave home.", "structureVi": "should + V: nên làm gì\ncheck + danh từ: kiểm tra", "structureEn": "should + V: advice\ncheck + noun: make sure"}, {"text": "It's best to check when the train leaves before leaving the house.", "structureVi": "It's best to + V: tốt nhất là\nwhen + mệnh đề: khi nào", "structureEn": "It's best to + V: strong advice\nwhen + clause: indirect question"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Chuyến đi bị rút ngắn vì một thành viên trong đoàn bị ốm.', $j$[{"text": "The trip was shortened because one member of the group was ill.", "structureVi": "be + V3: bị động (chuyến đi bị rút ngắn)\nmember of the group: thành viên trong đoàn", "structureEn": "be + V3: passive voice\nmember of the group: person in a group"}, {"text": "They cut the trip short since someone in the group got sick.", "structureVi": "cut short: rút ngắn\nsince + mệnh đề: vì", "structureEn": "cut short: end early\nsince + clause: reason"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Tôi thích đi tàu hơn đi máy bay vì có thể ngắm cảnh.', $j$[{"text": "I prefer traveling by train to flying because I can enjoy the scenery.", "structureVi": "prefer A to B: thích A hơn B\nbecause + mệnh đề: vì", "structureEn": "prefer A to B: like A more than B\nbecause + clause: reason"}, {"text": "I like taking the train more than flying since I can look at the view.", "structureVi": "like A more than B: thích A hơn B\nsince + mệnh đề: vì", "structureEn": "like A more than B: preference\nsince + clause: reason"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Khách du lịch cần mang theo giấy tờ tùy thân khi làm thủ tục.', $j$[{"text": "Tourists need to carry identification when they go through check-in.", "structureVi": "need to + V: cần làm gì\nwhen + mệnh đề: khi", "structureEn": "need to + V: necessity\nwhen + clause: time"}, {"text": "Travelers must bring their ID documents when checking in.", "structureVi": "must + V: phải làm gì\nwhen + V-ing: khi làm gì", "structureEn": "must + V: obligation\nwhen + V-ing: shortened clause"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Chúng tôi thuê xe đạp để khám phá những con đường ven biển.', $j$[{"text": "We rented bicycles to explore the roads along the coast.", "structureVi": "rent + danh từ: thuê\nto + V: để làm gì", "structureEn": "rent + noun: pay to use\nto + V: purpose"}, {"text": "We hired bikes in order to discover the coastal roads.", "structureVi": "hire: thuê\nin order to + V: để làm gì", "structureEn": "hire: rent for a short time\nin order to + V: purpose"}]$j$::jsonb),
  ('intermediate', 'transportation-travel', 'Tài xế chọn một tuyến đường khác để tránh giờ cao điểm.', $j$[{"text": "The driver chose a different route to avoid rush hour.", "structureVi": "choose + danh từ: chọn\navoid + danh từ: tránh", "structureEn": "choose + noun: pick\navoid + noun: stay away from"}, {"text": "The driver took another road so he could avoid the rush hour traffic.", "structureVi": "take a road: đi đường\nso + chủ ngữ + could: để có thể", "structureEn": "take a road: use a route\nso + subject + could: purpose"}]$j$::jsonb),
