  ('intermediate', 'school-education', 'Giáo viên khuyến khích học sinh đặt câu hỏi khi chưa hiểu bài.', $j$[{"text": "The teacher encourages students to ask questions when they don't understand the lesson.", "structureVi": "encourage + người + to + V: khuyến khích ai làm gì\nwhen + mệnh đề: khi", "structureEn": "encourage + person + to + V: motivate someone\nwhen + clause: time"}, {"text": "Teachers urge their students to ask if something isn't clear.", "structureVi": "urge + người + to + V: thúc giục ai\nif + mệnh đề: nếu", "structureEn": "urge + person + to + V: strongly encourage\nif + clause: condition"}]$j$::jsonb),
