  ('intermediate', 'school-education', 'Tôi thường ghi chú những ví dụ quan trọng trong lúc nghe giảng.', $j$[{"text": "I usually take notes of the important examples while listening to the lecture.", "structureVi": "take notes: ghi chú\nwhile + V-ing: trong lúc", "structureEn": "take notes: write down\nwhile + V-ing: at the same time"}, {"text": "I often write down key examples as I listen to the teacher.", "structureVi": "write down: ghi lại\nas + mệnh đề: trong lúc", "structureEn": "write down: record\nas + clause: at the same time"}]$j$::jsonb),
