  ('intermediate', 'food-drink', 'Quán này nổi tiếng vì phục vụ món địa phương với giá hợp lý.', $j$[{"text": "This restaurant is famous for serving local dishes at reasonable prices.", "structureVi": "be famous for + V-ing: nổi tiếng vì\nat reasonable prices: giá hợp lý", "structureEn": "be famous for + V-ing: known for\nat reasonable prices: fair cost"}, {"text": "This place is well known for its local food at fair prices.", "structureVi": "be well known for + danh từ: nổi tiếng vì\nat fair prices: giá phải chăng", "structureEn": "be well known for + noun: famous for\nat fair prices: reasonable cost"}]$j$::jsonb),
  ('intermediate', 'food-drink', 'Tôi giảm lượng đường trong cà phê nhưng vẫn giữ được hương vị.', $j$[{"text": "I reduced the amount of sugar in my coffee but I can still keep the flavor.", "structureVi": "reduce + danh từ: giảm\nbut: nhưng", "structureEn": "reduce + noun: make less\nbut: contrast"}, {"text": "I use less sugar in my coffee, yet it still tastes good.", "structureVi": "less + danh từ không đếm được: ít hơn\nyet: nhưng", "structureEn": "less + uncountable noun: smaller amount\nyet: however"}]$j$::jsonb),
  ('intermediate', 'food-drink', 'Thức ăn cần được bảo quản đúng cách để tránh bị hỏng.', $j$[{"text": "Food needs to be stored properly to avoid spoiling.", "structureVi": "need to be + V3: cần được (bị động)\navoid + V-ing: tránh", "structureEn": "need to be + V3: passive necessity\navoid + V-ing: not allow"}, {"text": "You should keep food the right way so it doesn't go bad.", "structureVi": "should + V: nên\ngo bad: bị hỏng", "structureEn": "should + V: advice\ngo bad: spoil"}]$j$::jsonb),
  ('intermediate', 'food-drink', 'Chia sẻ món ăn truyền thống là cách thú vị để tìm hiểu văn hóa.', $j$[{"text": "Sharing traditional food is an interesting way to learn about a culture.", "structureVi": "V-ing làm chủ ngữ: chia sẻ\na way to + V: cách để", "structureEn": "V-ing as subject: sharing\na way to + V: method of doing"}, {"text": "Sharing traditional dishes is a fun way to understand another culture.", "structureVi": "a fun way to + V: cách thú vị để\nunderstand + danh từ: hiểu", "structureEn": "a fun way to + V: enjoyable method\nunderstand + noun: know"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Chúng tôi mua vé sớm vì buổi biểu diễn thường kín chỗ.', $j$[{"text": "We bought tickets early because the show is usually fully booked.", "structureVi": "because + mệnh đề: vì\nfully booked: kín chỗ", "structureEn": "because + clause: reason\nfully booked: no seats left"}, {"text": "We got our tickets in advance since the performance often sells out.", "structureVi": "in advance: trước\nsell out: bán hết", "structureEn": "in advance: beforehand\nsell out: all tickets are sold"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Tôi thích những bộ phim khiến khán giả suy nghĩ sau khi xem xong.', $j$[{"text": "I like films that make the audience think after they finish watching.", "structureVi": "films that + V: phim mà\nmake + người + V: khiến ai làm gì", "structureEn": "films that + V: relative clause\nmake + person + V: cause someone to"}, {"text": "I enjoy movies that get viewers thinking once they are over.", "structureVi": "movies that + V: mệnh đề quan hệ\nget + người + V-ing: khiến ai bắt đầu", "structureEn": "movies that + V: relative clause\nget + person + V-ing: cause to start"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Cô ấy dành cuối tuần học nhiếp ảnh thay vì ở nhà xem tivi.', $j$[{"text": "She spends her weekends learning photography instead of staying home watching TV.", "structureVi": "spend + thời gian + V-ing: dành thời gian làm gì\ninstead of + V-ing: thay vì", "structureEn": "spend + time + V-ing: use time doing\ninstead of + V-ing: rather than"}, {"text": "She uses her weekends to study photography rather than sit at home and watch television.", "structureVi": "use + thời gian + to + V: dùng thời gian để\nrather than + V: thay vì", "structureEn": "use + time + to + V: purpose\nrather than + V: instead of"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Lễ hội có nhiều hoạt động miễn phí dành cho gia đình.', $j$[{"text": "The festival has many free activities for families.", "structureVi": "have + danh từ: có\nfor + người: dành cho", "structureEn": "have + noun: include\nfor + person: intended for"}, {"text": "There are plenty of free events for the whole family at the festival.", "structureVi": "There are + danh từ số nhiều: có\nplenty of: nhiều", "structureEn": "There are + plural noun: exist\nplenty of: a lot of"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Tôi nghe sách nói khi đi bộ đến nơi làm việc.', $j$[{"text": "I listen to audiobooks while walking to work.", "structureVi": "listen to + danh từ: nghe\nwhile + V-ing: trong lúc", "structureEn": "listen to + noun: hear on purpose\nwhile + V-ing: at the same time"}, {"text": "I like to listen to audio books on my way to the office.", "structureVi": "on one's way to: trên đường đến\nlike to + V: thích làm gì", "structureEn": "on one's way to: while traveling to\nlike to + V: enjoy"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Nhóm bạn chọn một trò chơi mà mọi người đều có thể tham gia.', $j$[{"text": "My friends picked a game that everyone can join.", "structureVi": "a game that + V: trò chơi mà\neveryone + V số ít: mọi người", "structureEn": "a game that + V: relative clause\neveryone + singular verb"}, {"text": "The group chose a game which all of us are able to play.", "structureVi": "which + V: mệnh đề quan hệ\nbe able to + V: có thể", "structureEn": "which + V: relative clause\nbe able to + V: can"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Buổi triển lãm giới thiệu tác phẩm của các nghệ sĩ trẻ trong vùng.', $j$[{"text": "The exhibition introduces works by young artists from the region.", "structureVi": "introduce + danh từ: giới thiệu\nworks by + người: tác phẩm của", "structureEn": "introduce + noun: present\nworks by + person: art made by"}, {"text": "The show presents pieces created by young local artists.", "structureVi": "present: trình bày, giới thiệu\ncreated by: do ai tạo ra", "structureEn": "present: show\ncreated by: made by (reduced relative clause)"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Tôi cần một khoảng thời gian yên tĩnh sau tuần làm việc căng thẳng.', $j$[{"text": "I need a quiet period after a stressful week of work.", "structureVi": "need + danh từ: cần\nafter + danh từ: sau", "structureEn": "need + noun: require\nafter + noun: later than"}, {"text": "I need some peaceful time after a tense working week.", "structureVi": "some + danh từ: một ít\ntense: căng thẳng", "structureEn": "some + noun: an amount\ntense: stressful"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Chúng tôi đổi lịch xem phim vì một người bạn phải làm thêm giờ.', $j$[{"text": "We changed the movie schedule because a friend had to work overtime.", "structureVi": "change + danh từ: đổi\nhad to + V: đã phải", "structureEn": "change + noun: alter\nhad to + V: past obligation"}, {"text": "We moved our film night since one of our friends had to stay late at work.", "structureVi": "move: dời lịch\nstay late: ở lại muộn", "structureEn": "move: reschedule\nstay late: work after hours"}]$j$::jsonb),
  ('intermediate', 'entertainment-leisure', 'Sở thích mới giúp tôi gặp gỡ những người có cùng mối quan tâm.', $j$[{"text": "A new hobby helps me meet people who share the same interests.", "structureVi": "help + người + V: giúp ai làm gì\npeople who + V: những người mà", "structureEn": "help + person + V: assist\npeople who + V: relative clause"}, {"text": "Having a new pastime lets me get to know people with similar interests.", "structureVi": "let + người + V: cho phép\nget to know: làm quen", "structureEn": "let + person + V: allow\nget to know: become familiar with"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Khu dân cư đặt thêm thùng phân loại rác để khuyến khích tái chế.', $j$[{"text": "The residential area has added more waste sorting bins to encourage recycling.", "structureVi": "has + V3: hiện tại hoàn thành\nto + V: để (mục đích)", "structureEn": "has + V3: present perfect\nto + V: purpose"}, {"text": "The neighborhood put in extra recycling bins so people would sort their rubbish.", "structureVi": "put in: lắp đặt\nso + chủ ngữ + would + V: để mà", "structureEn": "put in: install\nso + subject + would + V: purpose"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Lượng mưa thấp kéo dài khiến người nông dân lo lắng về vụ mùa.', $j$[{"text": "Long periods of low rainfall make farmers worry about their harvest.", "structureVi": "make + người + V: khiến ai làm gì\nworry about: lo lắng về", "structureEn": "make + person + V: cause\nworry about: be anxious about"}, {"text": "A long dry spell is worrying farmers about this year's crop.", "structureVi": "is + V-ing: đang làm\ndry spell: đợt khô hạn", "structureEn": "is + V-ing: happening now\ndry spell: period without rain"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Chúng tôi mang bình nước cá nhân để giảm số chai nhựa dùng một lần.', $j$[{"text": "We bring our own water bottles to reduce the number of single-use plastic bottles.", "structureVi": "reduce the number of: giảm số lượng\nsingle-use: dùng một lần", "structureEn": "reduce the number of: make fewer\nsingle-use: used once"}, {"text": "We carry reusable bottles in order to cut down on disposable plastic ones.", "structureVi": "in order to + V: để\ncut down on: giảm", "structureEn": "in order to + V: purpose\ncut down on: reduce"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Nhiều loài chim quay lại khu vực này sau khi cây cối được phục hồi.', $j$[{"text": "Many bird species have returned to this area since the trees were restored.", "structureVi": "have + V3: hiện tại hoàn thành\nsince + mệnh đề: kể từ khi", "structureEn": "have + V3: present perfect\nsince + clause: from a point in time"}, {"text": "Lots of kinds of birds came back here after the forest grew back.", "structureVi": "lots of: nhiều\ncome back: quay lại", "structureEn": "lots of: many\ncome back: return"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Thành phố khuyến khích người dân sử dụng phương tiện công cộng để giảm khí thải.', $j$[{"text": "The city encourages residents to use public transport to reduce emissions.", "structureVi": "encourage + người + to + V: khuyến khích\nto + V: để", "structureEn": "encourage + person + to + V: motivate\nto + V: purpose"}, {"text": "The city wants people to take buses and trains so there is less pollution.", "structureVi": "want + người + to + V: muốn ai\nso + mệnh đề: để", "structureEn": "want + person + to + V: wish\nso + clause: result"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Nếu không tiết kiệm nước, khu vực có thể đối mặt với tình trạng thiếu nước.', $j$[{"text": "If we don't save water, the region could face a water shortage.", "structureVi": "If + hiện tại đơn, could + V: điều kiện\nface + danh từ: đối mặt", "structureEn": "If + present simple, could + V: possibility\nface + noun: confront"}, {"text": "Unless we conserve water, the area may run short of it.", "structureVi": "Unless = If not: nếu không\nrun short of: thiếu", "structureEn": "Unless = If not: condition\nrun short of: not have enough"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Các tình nguyện viên dọn rác dọc bờ sông vào mỗi cuối tháng.', $j$[{"text": "Volunteers clean up the garbage along the river at the end of every month.", "structureVi": "clean up: dọn dẹp\nat the end of: vào cuối", "structureEn": "clean up: tidy\nat the end of: final part"}, {"text": "Volunteers collect rubbish from the riverbank each month end.", "structureVi": "collect: thu gom\neach month end: cuối mỗi tháng", "structureEn": "collect: gather\neach month end: last days of a month"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Trồng cây ở đô thị giúp tạo bóng mát và cải thiện chất lượng không khí.', $j$[{"text": "Planting trees in cities creates shade and improves air quality.", "structureVi": "V-ing làm chủ ngữ: trồng\ncreate + danh từ: tạo ra", "structureEn": "V-ing as subject: planting\ncreate + noun: make"}, {"text": "Trees in urban areas give shade and make the air cleaner.", "structureVi": "give + danh từ: mang lại\nmake + vật + tính từ: làm cho", "structureEn": "give + noun: provide\nmake + thing + adjective: cause a state"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Du khách được yêu cầu không cho động vật hoang dã ăn.', $j$[{"text": "Visitors are asked not to feed wild animals.", "structureVi": "be asked not to + V: được yêu cầu không\nwild animals: động vật hoang dã", "structureEn": "be asked not to + V: passive request\nwild animals: not tame"}, {"text": "Tourists must not give food to wildlife.", "structureVi": "must not + V: cấm làm gì\ngive food to: cho ăn", "structureEn": "must not + V: prohibition\ngive food to: feed"}]$j$::jsonb),
  ('intermediate', 'nature-environment', 'Thay đổi nhỏ trong sinh hoạt có thể góp phần giảm tác động đến môi trường.', $j$[{"text": "Small changes in daily habits can help reduce our impact on the environment.", "structureVi": "can help + V: có thể giúp\nimpact on: tác động đến", "structureEn": "can help + V: may contribute\nimpact on: effect on"}, {"text": "Little lifestyle adjustments can lessen the effect we have on nature.", "structureVi": "lessen: giảm bớt\nthe effect we have on: tác động của chúng ta", "structureEn": "lessen: reduce\nthe effect we have on: relative clause without that"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Ứng dụng mới cho phép người dùng đồng bộ dữ liệu giữa nhiều thiết bị.', $j$[{"text": "The new app allows users to sync data between several devices.", "structureVi": "allow + người + to + V: cho phép ai làm gì\nbetween + danh từ: giữa", "structureEn": "allow + person + to + V: permit\nbetween + noun: connecting items"}, {"text": "The new application lets people keep their data in sync across multiple devices.", "structureVi": "let + người + V: cho phép\nkeep + vật + in sync: giữ đồng bộ", "structureEn": "let + person + V: allow\nkeep + thing + in sync: stay matched"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Tôi bật xác thực hai bước để bảo vệ tài khoản cá nhân.', $j$[{"text": "I turned on two-step verification to protect my personal account.", "structureVi": "turn on: bật\nto + V: để bảo vệ", "structureEn": "turn on: activate\nto + V: purpose"}, {"text": "I enabled two-factor authentication so that my account stays safe.", "structureVi": "enable: bật\nso that + mệnh đề: để mà", "structureEn": "enable: turn on\nso that + clause: purpose"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Các nhà nghiên cứu đang thử nghiệm vật liệu nhẹ hơn cho pin.', $j$[{"text": "Researchers are testing lighter materials for batteries.", "structureVi": "are + V-ing: đang thử nghiệm\nlighter: nhẹ hơn", "structureEn": "are + V-ing: in progress\nlighter: comparative of light"}, {"text": "Scientists are trying out lighter materials to use in batteries.", "structureVi": "try out: thử nghiệm\nto + V: để dùng", "structureEn": "try out: test\nto + V: purpose"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Kết nối không ổn định khiến cuộc họp trực tuyến bị gián đoạn vài lần.', $j$[{"text": "An unstable connection interrupted the online meeting several times.", "structureVi": "interrupt + danh từ: làm gián đoạn\nseveral times: vài lần", "structureEn": "interrupt + noun: break\nseveral times: more than once"}, {"text": "The online meeting was cut off a few times because the connection was unreliable.", "structureVi": "be + V3: bị động\nbecause + mệnh đề: vì", "structureEn": "be + V3: passive\nbecause + clause: reason"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Trước khi cài phần mềm, hãy kiểm tra nhà phát triển và quyền truy cập.', $j$[{"text": "Before installing software, check the developer and the permissions it requests.", "structureVi": "Before + V-ing: trước khi\ncheck + danh từ: kiểm tra", "structureEn": "Before + V-ing: before + gerund\ncheck + noun: verify"}, {"text": "You should look at who made the program and what access it asks for before you install it.", "structureVi": "who + V: ai\nwhat + mệnh đề: cái gì", "structureEn": "who + V: noun clause\nwhat + clause: noun clause"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Công cụ dịch tự động hữu ích nhưng vẫn có thể bỏ sót sắc thái ngôn ngữ.', $j$[{"text": "Automatic translation tools are useful but can still miss language nuances.", "structureVi": "be useful: hữu ích\nmiss + danh từ: bỏ sót", "structureEn": "be useful: helpful\nmiss + noun: fail to notice"}, {"text": "Machine translators are helpful, but they may overlook subtle meanings.", "structureVi": "helpful: hữu ích\noverlook: bỏ qua", "structureEn": "helpful: useful\noverlook: fail to see"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Dữ liệu được sao lưu định kỳ sẽ dễ khôi phục khi thiết bị gặp sự cố.', $j$[{"text": "Data that is backed up regularly is easier to restore when a device fails.", "structureVi": "Data that + V: dữ liệu mà\neasier to + V: dễ hơn để", "structureEn": "Data that + V: relative clause\neasier to + V: comparative"}, {"text": "If you back up your data often, it is simple to recover it when the device breaks.", "structureVi": "If + hiện tại đơn, mệnh đề: điều kiện\nit is simple to + V: dễ để", "structureEn": "If + present simple: condition\nit is simple to + V: easy to do"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Cảm biến giúp nông dân theo dõi độ ẩm của đất chính xác hơn.', $j$[{"text": "Sensors help farmers monitor soil moisture more accurately.", "structureVi": "help + người + V: giúp ai\nmore accurately: chính xác hơn", "structureEn": "help + person + V: assist\nmore accurately: comparative adverb"}, {"text": "Farmers can use sensors to measure how wet the soil is with greater precision.", "structureVi": "use A to + V: dùng A để\nhow + tính từ + mệnh đề: mức độ", "structureEn": "use A to + V: purpose\nhow + adjective + clause: degree"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Công ty cập nhật hệ thống để sửa lỗi và tăng cường bảo mật.', $j$[{"text": "The company updated its system to fix errors and strengthen security.", "structureVi": "to + V: để\nfix + danh từ: sửa", "structureEn": "to + V: purpose\nfix + noun: repair"}, {"text": "The company has upgraded its system in order to correct bugs and improve safety.", "structureVi": "in order to + V: để\nimprove: cải thiện", "structureEn": "in order to + V: purpose\nimprove: make better"}]$j$::jsonb),
  ('intermediate', 'science-technology', 'Trẻ em cần được hướng dẫn cách đánh giá thông tin trên mạng.', $j$[{"text": "Children need to be taught how to evaluate information online.", "structureVi": "need to be + V3: cần được\nhow to + V: cách", "structureEn": "need to be + V3: passive necessity\nhow to + V: method"}, {"text": "Kids should learn how to judge whether what they read on the internet is true.", "structureVi": "should + V: nên\nwhether + mệnh đề: liệu có", "structureEn": "should + V: advice\nwhether + clause: indirect question"}]$j$::jsonb),
  ('intermediate', 'culture-society', 'Trong gia đình tôi, các quyết định lớn thường được thảo luận cùng nhau.', $j$[{"text": "In my family, major decisions are usually discussed together.", "structureVi": "in + danh từ: trong\nbe + V3: bị động", "structureEn": "in + noun: within\nbe + V3: passive"}, {"text": "In my household we usually talk over big decisions as a group.", "structureVi": "talk over: bàn bạc\nas a group: cùng nhau", "structureEn": "talk over: discuss\nas a group: together"}]$j$::jsonb),
  ('intermediate', 'culture-society', 'Một số phong tục thay đổi theo thời gian nhưng vẫn giữ ý nghĩa cốt lõi.', $j$[{"text": "Some customs change over time but keep their core meaning.", "structureVi": "over time: theo thời gian\nkeep + danh từ: giữ", "structureEn": "over time: gradually\nkeep + noun: retain"}, {"text": "Certain traditions evolve with the years yet still carry their main meaning.", "structureVi": "evolve: phát triển, thay đổi\nyet: nhưng", "structureEn": "evolve: change gradually\nyet: however"}]$j$::jsonb),
  ('intermediate', 'culture-society', 'Lễ hội địa phương thu hút du khách và tạo thêm thu nhập cho người dân.', $j$[{"text": "Local festivals attract tourists and create extra income for residents.", "structureVi": "attract + danh từ: thu hút\ncreate + danh từ: tạo ra", "structureEn": "attract + noun: draw in\ncreate + noun: produce"}, {"text": "The local festival brings in visitors and gives people more money.", "structureVi": "bring in: đem lại\ngive + người + vật: mang đến cho ai", "structureEn": "bring in: attract\ngive + person + thing: provide"}]$j$::jsonb),
  ('intermediate', 'culture-society', 'Người trẻ ngày nay kết hợp trang phục truyền thống với phong cách hiện đại.', $j$[{"text": "Young people today combine traditional clothing with a modern style.", "structureVi": "combine A with B: kết hợp A với B\ntoday: ngày nay", "structureEn": "combine A with B: mix\ntoday: nowadays"}, {"text": "These days young people mix traditional outfits with modern fashion.", "structureVi": "mix A with B: trộn A với B\nthese days: ngày nay", "structureEn": "mix A with B: blend\nthese days: nowadays"}]$j$::jsonb),
