  ('intermediate', 'sports-fitness', 'Người mới bắt đầu nên đặt mục tiêu thực tế và theo dõi tiến bộ.', $j$[{"text": "Beginners should set realistic goals and track their progress.", "structureVi": "should + V: nên\nset goals: đặt mục tiêu", "structureEn": "should + V: advice\nset goals: decide targets"}, {"text": "People who are just starting out ought to aim for achievable targets and keep a record of how they improve.", "structureVi": "people who + V: người mà\nkeep a record of: ghi lại", "structureEn": "people who + V: relative clause\nkeep a record of: track"}]$j$::jsonb),
