  ('intermediate', 'arts-literature', 'Bức ảnh khiến người xem chú ý đến sự tương phản giữa ánh sáng và bóng tối.', $j$[{"text": "The photograph draws the viewer's attention to the contrast between light and shadow.", "structureVi": "draw attention to: thu hút sự chú ý đến\ncontrast between A and B: sự tương phản giữa", "structureEn": "draw attention to: make notice\ncontrast between A and B: difference"}, {"text": "The picture makes people notice how light and dark differ.", "structureVi": "make + người + V: khiến ai\nhow + mệnh đề: cách", "structureEn": "make + person + V: cause\nhow + clause: manner"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Tôi đọc bản dịch trước rồi tìm hiểu thêm về nguyên tác.', $j$[{"text": "I read the translation first and then learn more about the original work.", "structureVi": "first and then: trước rồi sau\nlearn more about: tìm hiểu thêm", "structureEn": "first and then: sequence\nlearn more about: find out"}, {"text": "I start with a translated version and later look into the original text.", "structureVi": "start with: bắt đầu với\nlook into: tìm hiểu", "structureEn": "start with: begin\nlook into: investigate"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Buổi triển lãm đặt các tác phẩm hiện đại bên cạnh tranh dân gian.', $j$[{"text": "The exhibition places modern works next to folk paintings.", "structureVi": "place A next to B: đặt A cạnh B\nfolk paintings: tranh dân gian", "structureEn": "place A next to B: put beside\nfolk paintings: traditional art"}, {"text": "The show displays contemporary pieces beside traditional folk art.", "structureVi": "display A beside B: trưng bày A cạnh B\ncontemporary: hiện đại", "structureEn": "display A beside B: show side by side\ncontemporary: modern"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Một bài phê bình tốt giải thích quan điểm thay vì chỉ khen hoặc chê.', $j$[{"text": "A good review explains opinions instead of simply praising or criticizing.", "structureVi": "instead of + V-ing: thay vì\nexplain + danh từ: giải thích", "structureEn": "instead of + V-ing: rather than\nexplain + noun: make clear"}, {"text": "A strong critique gives reasons rather than just saying something is good or bad.", "structureVi": "give reasons: đưa ra lý do\nrather than + V-ing: thay vì", "structureEn": "give reasons: justify\nrather than + V-ing: instead of"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Nhà thơ sử dụng hình ảnh thiên nhiên để diễn tả nỗi nhớ quê nhà.', $j$[{"text": "The poet uses images of nature to express nostalgia for his hometown.", "structureVi": "use A to + V: dùng A để\nexpress + danh từ: diễn tả", "structureEn": "use A to + V: purpose\nexpress + noun: show"}, {"text": "The poet describes his homesickness with pictures from nature.", "structureVi": "describe: miêu tả\nwith + danh từ: bằng", "structureEn": "describe: depict\nwith + noun: by means of"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Câu chuyện thay đổi góc nhìn của người kể ở từng chương.', $j$[{"text": "The story changes the narrator's point of view in each chapter.", "structureVi": "change + danh từ: thay đổi\nin each chapter: ở mỗi chương", "structureEn": "change + noun: alter\nin each chapter: every chapter"}, {"text": "In every chapter, a different person tells the story.", "structureVi": "In every + danh từ: trong mỗi\na different person: một người khác", "structureEn": "In every + noun: each one\na different person: another"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Các nghệ sĩ địa phương hợp tác để tạo nên một không gian biểu diễn chung.', $j$[{"text": "Local artists collaborate to create a shared performance space.", "structureVi": "collaborate to + V: hợp tác để\na shared + danh từ: chung", "structureEn": "collaborate to + V: work together\na shared + noun: used by all"}, {"text": "Artists from the area work together to build a common stage.", "structureVi": "work together to + V: cùng làm để\ncommon: chung", "structureEn": "work together to + V: cooperate\ncommon: shared"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Tôi ghi lại những câu văn hay để học cách sử dụng ngôn ngữ.', $j$[{"text": "I write down good sentences to learn how to use the language.", "structureVi": "write down: ghi lại\nlearn how to + V: học cách", "structureEn": "write down: record\nlearn how to + V: study a method"}, {"text": "I copy beautiful lines so that I can see how language is used.", "structureVi": "so that + mệnh đề: để\nhow + mệnh đề: cách", "structureEn": "so that + clause: purpose\nhow + clause: manner"}]$j$::jsonb),
  ('intermediate', 'arts-literature', 'Âm nhạc không lời giúp tôi tập trung khi đọc tài liệu dài.', $j$[{"text": "Instrumental music helps me concentrate when I read long documents.", "structureVi": "help + người + V: giúp ai\nwhen + mệnh đề: khi", "structureEn": "help + person + V: assist\nwhen + clause: time"}, {"text": "Music without lyrics lets me focus while I'm reading lengthy texts.", "structureVi": "without + danh từ: không có\nwhile + mệnh đề: trong lúc", "structureEn": "without + noun: lacking\nwhile + clause: at the same time"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Một số người dành vài phút thiền mỗi sáng để bắt đầu ngày mới bình tĩnh hơn.', $j$[{"text": "Some people spend a few minutes meditating every morning to start the day more calmly.", "structureVi": "spend + thời gian + V-ing: dành thời gian\nmore calmly: bình tĩnh hơn", "structureEn": "spend + time + V-ing: use time\nmore calmly: comparative adverb"}, {"text": "Some meditate for a few minutes each morning so they can begin the day feeling calmer.", "structureVi": "so + chủ ngữ + can: để có thể\nfeeling + tính từ: cảm thấy", "structureEn": "so + subject + can: purpose\nfeeling + adjective: state"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Ngôi chùa mở lớp tìm hiểu lịch sử kiến trúc cho khách tham quan.', $j$[{"text": "The temple offers a class on architectural history for visitors.", "structureVi": "offer + danh từ: cung cấp\nfor + người: dành cho", "structureEn": "offer + noun: provide\nfor + person: intended for"}, {"text": "The pagoda runs a course about the history of its architecture for tourists.", "structureVi": "run a course: mở lớp\nabout + danh từ: về", "structureEn": "run a course: organize\nabout + noun: on the topic of"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Gia đình tôn trọng lựa chọn tín ngưỡng khác nhau của mỗi thành viên.', $j$[{"text": "My family respects each member's different religious choices.", "structureVi": "respect + danh từ: tôn trọng\neach member's: của mỗi thành viên", "structureEn": "respect + noun: honor\neach member's: possessive"}, {"text": "In my family everyone's different beliefs are respected.", "structureVi": "be + V3: bị động\neveryone's: của mọi người", "structureEn": "be + V3: passive\neveryone's: possessive"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Buổi sinh hoạt nhấn mạnh lòng biết ơn và sự quan tâm đến cộng đồng.', $j$[{"text": "The gathering emphasizes gratitude and care for the community.", "structureVi": "emphasize + danh từ: nhấn mạnh\ncare for: quan tâm đến", "structureEn": "emphasize + noun: stress\ncare for: look after"}, {"text": "The meeting highlights thankfulness and concern for others in the community.", "structureVi": "highlight: nhấn mạnh\nconcern for: sự quan tâm đến", "structureEn": "highlight: stress\nconcern for: care about"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Tôi đọc về nhiều truyền thống tâm linh để hiểu cách chúng nhìn nhận cuộc sống.', $j$[{"text": "I read about many spiritual traditions to understand how they view life.", "structureVi": "read about: đọc về\nto + V: để hiểu", "structureEn": "read about: study\nto + V: purpose"}, {"text": "I study different spiritual paths in order to see how each looks at life.", "structureVi": "study: nghiên cứu\nin order to + V: để", "structureEn": "study: learn about\nin order to + V: purpose"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Không gian yên tĩnh giúp người tham dự tập trung trong buổi lễ.', $j$[{"text": "A quiet space helps participants concentrate during the ceremony.", "structureVi": "help + người + V: giúp ai\nduring + danh từ: trong suốt", "structureEn": "help + person + V: assist\nduring + noun: throughout"}, {"text": "A peaceful setting lets attendees focus throughout the ritual.", "structureVi": "let + người + V: cho phép\nthroughout: suốt", "structureEn": "let + person + V: allow\nthroughout: during the whole time"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Các tình nguyện viên chuẩn bị bữa ăn cho người có hoàn cảnh khó khăn.', $j$[{"text": "Volunteers prepare meals for people in difficult circumstances.", "structureVi": "prepare + danh từ: chuẩn bị\npeople in + danh từ: những người ở trong", "structureEn": "prepare + noun: make ready\npeople in + noun: people experiencing"}, {"text": "Volunteers cook food for those who are going through hard times.", "structureVi": "those who + V: những người mà\ngo through: trải qua", "structureEn": "those who + V: relative clause\ngo through: experience"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Nghi thức truyền thống có thể mang ý nghĩa khác nhau với từng gia đình.', $j$[{"text": "Traditional rituals can have different meanings for each family.", "structureVi": "can + V: có thể\ndifferent meanings for: những ý nghĩa khác nhau với", "structureEn": "can + V: possibility\ndifferent meanings for: varied for"}, {"text": "A traditional ceremony may mean something different to every household.", "structureVi": "may + V: có thể\nmean something different: mang ý nghĩa khác", "structureEn": "may + V: possibility\nmean something different: have another meaning"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Cô ấy kết hợp việc suy ngẫm cá nhân với những hoạt động giúp đỡ người khác.', $j$[{"text": "She combines personal reflection with activities that help others.", "structureVi": "combine A with B: kết hợp A với B\nactivities that + V: những hoạt động mà", "structureEn": "combine A with B: mix\nactivities that + V: relative clause"}, {"text": "She balances thinking quietly about life with doing things to help other people.", "structureVi": "balance A with B: cân bằng\nthings to + V: những việc để", "structureEn": "balance A with B: keep equal\nthings to + V: purpose"}]$j$::jsonb),
  ('intermediate', 'religion-spirituality', 'Đối thoại tôn trọng giúp mọi người chia sẻ niềm tin mà không áp đặt.', $j$[{"text": "Respectful dialogue helps people share their beliefs without forcing them on others.", "structureVi": "help + người + V: giúp ai\nwithout + V-ing: mà không", "structureEn": "help + person + V: assist\nwithout + V-ing: not doing"}, {"text": "Talking respectfully lets everyone share what they believe without imposing it.", "structureVi": "let + người + V: cho phép\nwhat + mệnh đề: điều mà", "structureEn": "let + person + V: allow\nwhat + clause: noun clause"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Người thuê nhà nên đọc kỹ các điều khoản trước khi ký hợp đồng.', $j$[{"text": "Tenants should read the terms carefully before signing the contract.", "structureVi": "should + V: nên\nbefore + V-ing: trước khi", "structureEn": "should + V: advice\nbefore + V-ing: before + gerund"}, {"text": "People renting a home ought to go through the conditions closely before they sign the agreement.", "structureVi": "people + V-ing: người đang\ngo through: xem xét kỹ", "structureEn": "people + V-ing: reduced relative clause\ngo through: examine"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Quy định mới yêu cầu cửa hàng niêm yết giá rõ ràng cho khách hàng.', $j$[{"text": "The new regulation requires shops to display clear prices for customers.", "structureVi": "require + danh từ + to + V: yêu cầu ai làm gì\ndisplay: niêm yết", "structureEn": "require + noun + to + V: make someone do\ndisplay: show publicly"}, {"text": "Under the new rule, stores must show their prices clearly to shoppers.", "structureVi": "Under + danh từ: theo\nmust + V: phải", "structureEn": "Under + noun: according to\nmust + V: obligation"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Nhân chứng cung cấp thông tin để cơ quan điều tra xác minh vụ việc.', $j$[{"text": "Witnesses provide information so that investigators can verify the incident.", "structureVi": "provide + danh từ: cung cấp\nso that + can: để có thể", "structureEn": "provide + noun: give\nso that + can: purpose"}, {"text": "Eyewitnesses give details to help the authorities confirm what happened.", "structureVi": "give details: cung cấp chi tiết\nto help + V: để giúp", "structureEn": "give details: provide information\nto help + V: purpose"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Người dân có thể yêu cầu giải thích nếu hồ sơ bị từ chối.', $j$[{"text": "Citizens can ask for an explanation if their application is rejected.", "structureVi": "ask for + danh từ: yêu cầu\nif + mệnh đề: nếu", "structureEn": "ask for + noun: request\nif + clause: condition"}, {"text": "People may request a reason when their file is turned down.", "structureVi": "request + danh từ: yêu cầu\nturn down: bác bỏ", "structureEn": "request + noun: ask for\nturn down: reject"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Luật giao thông được áp dụng nhằm bảo vệ tất cả người tham gia đường phố.', $j$[{"text": "Traffic laws are applied to protect everyone using the road.", "structureVi": "be + V3: bị động\nto + V: để bảo vệ", "structureEn": "be + V3: passive\nto + V: purpose"}, {"text": "Road rules are enforced in order to keep all road users safe.", "structureVi": "enforce: thi hành\nkeep + người + tính từ: giữ cho ai", "structureEn": "enforce: make people follow\nkeep + person + adjective: maintain"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Hai bên tìm cách giải quyết tranh chấp thông qua hòa giải.', $j$[{"text": "The two sides are trying to settle the dispute through mediation.", "structureVi": "try to + V: cố gắng\nthrough + danh từ: thông qua", "structureEn": "try to + V: make an effort\nthrough + noun: by means of"}, {"text": "Both parties are working to resolve the conflict with the help of a mediator.", "structureVi": "work to + V: nỗ lực\nwith the help of: nhờ sự giúp đỡ của", "structureEn": "work to + V: make an effort\nwith the help of: by using"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Hợp đồng cần nêu rõ trách nhiệm của mỗi bên để tránh bất đồng.', $j$[{"text": "A contract should state each party's responsibilities clearly to avoid disagreements.", "structureVi": "should + V: nên\nto avoid + danh từ: để tránh", "structureEn": "should + V: advice\nto avoid + noun: purpose"}, {"text": "Agreements need to make clear what each side is responsible for so that no conflict arises.", "structureVi": "need to + V: cần\nwhat + mệnh đề: điều mà", "structureEn": "need to + V: necessity\nwhat + clause: noun clause"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Cơ quan chức năng đang xem xét phản ánh về tiếng ồn vào ban đêm.', $j$[{"text": "The authorities are looking into complaints about noise at night.", "structureVi": "are + V-ing: đang\nlook into: xem xét, điều tra", "structureEn": "are + V-ing: in progress\nlook into: investigate"}, {"text": "Officials are examining reports of night-time noise.", "structureVi": "examine: xem xét\nreports of + danh từ: phản ánh về", "structureEn": "examine: look at closely\nreports of + noun: complaints about"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Bằng chứng phải được kiểm tra trước khi đưa ra kết luận về một vụ việc.', $j$[{"text": "Evidence must be checked before a conclusion is drawn about a case.", "structureVi": "must be + V3: phải được (bị động)\nbefore + mệnh đề: trước khi", "structureEn": "must be + V3: passive obligation\nbefore + clause: time"}, {"text": "You have to verify the proof before you decide anything about an incident.", "structureVi": "have to + V: phải\ndecide about: quyết định về", "structureEn": "have to + V: obligation\ndecide about: reach a conclusion on"}]$j$::jsonb),
  ('intermediate', 'law-justice', 'Việc phổ biến kiến thức pháp luật giúp người dân hiểu rõ quyền và nghĩa vụ.', $j$[{"text": "Spreading legal knowledge helps people understand their rights and obligations.", "structureVi": "V-ing làm chủ ngữ: phổ biến\nrights and obligations: quyền và nghĩa vụ", "structureEn": "V-ing as subject: spreading\nrights and obligations: what you may and must do"}, {"text": "Teaching people about the law helps them know what they are entitled to and required to do.", "structureVi": "teach + người + about: dạy ai về\nbe entitled to: có quyền", "structureEn": "teach + person + about: educate\nbe entitled to: have the right"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Một quyết định khó khăn thường đòi hỏi cân nhắc giữa lợi ích cá nhân và trách nhiệm chung.', $j$[{"text": "A difficult decision often requires weighing personal interests against shared responsibility.", "structureVi": "require + V-ing: đòi hỏi việc\nweigh A against B: cân nhắc A với B", "structureEn": "require + V-ing: need an action\nweigh A against B: compare"}, {"text": "Making a hard choice usually means balancing what we want with what we owe to others.", "structureVi": "mean + V-ing: có nghĩa là\nwhat + mệnh đề: điều mà", "structureEn": "mean + V-ing: involve\nwhat + clause: noun clause"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Giữ lời hứa trở nên quan trọng nhất khi việc thực hiện nó không thuận tiện.', $j$[{"text": "Keeping a promise matters most when it is inconvenient to do so.", "structureVi": "V-ing làm chủ ngữ: giữ lời\nmost: nhất (trạng từ)", "structureEn": "V-ing as subject: keeping\nmost: superlative adverb"}, {"text": "Keeping your word is most important when it is not easy.", "structureVi": "your word: lời hứa\nmost + tính từ: nhất", "structureEn": "your word: promise\nmost + adjective: superlative"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Chúng ta nên xem xét hậu quả lâu dài trước khi hành động theo cảm xúc.', $j$[{"text": "We should consider the long-term consequences before acting on our emotions.", "structureVi": "should + V: nên\nbefore + V-ing: trước khi", "structureEn": "should + V: advice\nbefore + V-ing: before + gerund"}, {"text": "Before we act out of feeling, we ought to think about what will happen in the long run.", "structureVi": "Before + mệnh đề: trước khi\nin the long run: về lâu dài", "structureEn": "Before + clause: time\nin the long run: over a long time"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Một lời xin lỗi chân thành cần đi kèm nỗ lực sửa chữa sai lầm.', $j$[{"text": "A sincere apology needs to be accompanied by an effort to correct the mistake.", "structureVi": "need to be + V3: cần được\nbe accompanied by: đi kèm với", "structureEn": "need to be + V3: passive necessity\nbe accompanied by: go together with"}, {"text": "A genuine apology should come with an attempt to put things right.", "structureVi": "come with: đi kèm\nan attempt to + V: nỗ lực để", "structureEn": "come with: be paired with\nan attempt to + V: effort"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Công bằng không phải lúc nào cũng có nghĩa là đối xử với mọi người theo cùng một cách.', $j$[{"text": "Fairness doesn't always mean treating everyone in the same way.", "structureVi": "not always: không phải lúc nào\nmean + V-ing: có nghĩa là", "structureEn": "not always: partial negative\nmean + V-ing: involve"}, {"text": "Being fair is not necessarily the same as treating all people equally.", "structureVi": "not necessarily: chưa chắc\nthe same as: giống như", "structureEn": "not necessarily: not always\nthe same as: equal to"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Lắng nghe quan điểm trái ngược có thể giúp chúng ta nhận ra giới hạn của mình.', $j$[{"text": "Listening to opposing views can help us recognize our own limits.", "structureVi": "V-ing làm chủ ngữ: lắng nghe\nhelp + người + V: giúp ai", "structureEn": "V-ing as subject: listening\nhelp + person + V: assist"}, {"text": "Hearing different opinions can make us see where we are limited.", "structureVi": "make + người + V: khiến ai\nwhere + mệnh đề: nơi mà", "structureEn": "make + person + V: cause\nwhere + clause: noun clause"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Lòng can đảm đôi khi là thừa nhận rằng bản thân đã sai.', $j$[{"text": "Courage is sometimes admitting that you were wrong.", "structureVi": "sometimes: đôi khi\nadmit + that: thừa nhận rằng", "structureEn": "sometimes: not always\nadmit + that: confess"}, {"text": "Being brave can mean accepting that you made a mistake.", "structureVi": "can mean + V-ing: có thể có nghĩa là\naccept that: chấp nhận rằng", "structureEn": "can mean + V-ing: may involve\naccept that: acknowledge"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Một hành động tử tế có giá trị ngay cả khi không ai chứng kiến.', $j$[{"text": "A kind act has value even when no one is watching.", "structureVi": "even when + mệnh đề: ngay cả khi\nno one + V số ít: không ai", "structureEn": "even when + clause: despite the time\nno one + singular verb"}, {"text": "A good deed is worthwhile even if nobody sees it.", "structureVi": "worthwhile: đáng giá\neven if + mệnh đề: ngay cả nếu", "structureEn": "worthwhile: of value\neven if + clause: although possibly"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Trách nhiệm cá nhân cần được cân bằng với hoàn cảnh và nguồn lực sẵn có.', $j$[{"text": "Personal responsibility needs to be balanced with circumstances and available resources.", "structureVi": "need to be + V3: cần được\nbe balanced with: cân bằng với", "structureEn": "need to be + V3: passive necessity\nbe balanced with: weighed against"}, {"text": "We should weigh individual responsibility against our situation and what we have.", "structureVi": "weigh A against B: cân nhắc\nwhat we have: những gì sẵn có", "structureEn": "weigh A against B: compare\nwhat we have: resources"}]$j$::jsonb),
  ('intermediate', 'philosophy-ethics', 'Đặt câu hỏi về niềm tin của mình có thể mở ra cách nhìn mới.', $j$[{"text": "Questioning your own beliefs can open up a new way of seeing things.", "structureVi": "V-ing làm chủ ngữ: đặt câu hỏi\nopen up: mở ra", "structureEn": "V-ing as subject: questioning\nopen up: create"}, {"text": "Asking whether your beliefs are right may give you a fresh perspective.", "structureVi": "whether + mệnh đề: liệu\ngive + người + vật: mang lại", "structureEn": "whether + clause: indirect question\ngive + person + thing: provide"}]$j$::jsonb)
) as v(level, category, vietnamese, answers)
join public.prompts p
  on p.writing_type = 'sentence' and p.difficulty = v.level and p.category = v.category and p.prompt_text = v.vietnamese
on conflict (prompt_id) do nothing;
